// Restricted Markdown: create text nodes, never execute or insert model HTML.
export function inlineTokens(value){return String(value||'').split(/(\*\*[^*\n]+\*\*|`[^`\n]+`|\*[^*\n]+\*)/g).filter(Boolean).map(text=>text.startsWith('**')&&text.endsWith('**')?{type:'strong',text:text.slice(2,-2)}:text.startsWith('`')&&text.endsWith('`')?{type:'code',text:text.slice(1,-1)}:text.startsWith('*')&&text.endsWith('*')?{type:'em',text:text.slice(1,-1)}:{type:'text',text})}
export function messageBlocks(value){const lines=String(value||'').slice(0,60000).replaceAll('\r','').split('\n'),blocks=[];let code=null;
 for(const line of lines){if(/^```/.test(line.trim())){if(code){blocks.push({type:'code',text:code.join('\n')});code=null}else code=[];continue}if(code){code.push(line);continue}if(!line.trim())continue;const heading=/^#{1,4}\s+(.+)/.exec(line),bullet=/^\s*[-*•]\s+(.+)/.exec(line),number=/^\s*\d+[.)]\s+(.+)/.exec(line);blocks.push({type:heading?'heading':bullet?'bullet':number?'number':'paragraph',text:heading?.[1]||bullet?.[1]||number?.[1]||line})}if(code)blocks.push({type:'code',text:code.join('\n')});return blocks;
}
export function renderMessageText(value,{markdown=true}={}){const body=document.createElement('div');body.className='message-body';if(!markdown){body.textContent=value||'';return body}
 let list=null,listType='';for(const b of messageBlocks(value)){if(['bullet','number'].includes(b.type)){if(!list||listType!==b.type){list=document.createElement(b.type==='number'?'ol':'ul');listType=b.type;body.append(list)}const li=document.createElement('li');appendInline(li,b.text);list.append(li);continue}list=null;listType='';if(b.type==='code'){const pre=document.createElement('pre'),code=document.createElement('code');code.textContent=b.text;pre.append(code);body.append(pre);continue}const node=document.createElement(b.type==='heading'?'h4':'p');appendInline(node,b.text);body.append(node)}return body;
}
function appendInline(parent,text){for(const t of inlineTokens(text)){if(t.type==='text')parent.append(document.createTextNode(t.text));else{const n=document.createElement(t.type);n.textContent=t.text;parent.append(n)}}}
